import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"AppleSkinPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/apple-skin-pumpkin/README.md"},"headers":[],"relativePath":"packages/apple-skin-pumpkin/README.md","filePath":"packages/apple-skin-pumpkin/README.md","lastUpdated":1792508976000}`),l={name:`packages/apple-skin-pumpkin/README.md`},u={id:`appleskinpumpkin`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/apple-skin-pumpkin-v0.1.0`,"aria-label":`Release v0.1.0`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`span`,{class:`component-page-title__text`},[t(`AppleSkinPumpkin `),n(`a`,{class:`header-anchor`,href:`#appleskinpumpkin`,"aria-label":`Permalink to “AppleSkinPumpkin”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.1.0`})])]),c[1]||=r(`<p>The plugin syncs saturation and exhaustion so AppleSkin can show accurate food stats.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/packages/apple-skin-pumpkin/docs/" target="_blank" rel="noreferrer">plugin guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/plugins/apple-skin-pumpkin/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h2><p>Download <code>apple-skin-pumpkin.wasm</code> from the plugin&#39;s GitHub release, put it in your server&#39;s <code>plugins/</code> folder, and restart Pumpkin. On the first load, a full restart lets Pumpkin ask for the plugin&#39;s permissions; hot reload cannot prompt for them.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h2><p>Vanilla tells a client about saturation only when it reaches zero, and never sends exhaustion at all, which leaves the food tooltips AppleSkin draws behind by a tick. So the plugin reads every online player once per tick and sends the two values, plus whether the world heals players by food. It reads that game rule once per world rather than once per player, and sends only what moved since the last packet, so it sends nothing for a still player.</p><p>AppleSkin is a Java Edition mod, so Bedrock players are skipped.</p><h2 id="seeing-what-it-does" tabindex="-1">Seeing what it does <a class="header-anchor" href="#seeing-what-it-does" aria-label="Permalink to “Seeing what it does”">​</a></h2><p>Set <code>logging.level</code> to <code>debug</code> in your Pumpkin config. Every packet the plugin sends is then logged with the player and the value, along with players joining, leaving and being skipped. After one line for the first tick, ticks where nothing changed are silent, which is the point of only sending on a change.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Pumpkin asks you to approve these on the server console when it loads the plugin. It skips the question when the <code>[plugins]</code> table in <code>pumpkin.toml</code> lists all of them in <code>allowed_permissions</code> or sets <code>ask_permission_confirmation = false</code>. Pumpkin remembers your answer and asks again after the plugin file or this list changes.</p><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>http.outbound</code></td><td>Check Pumpkin Market for plugin updates.</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><p>This plugin registers no commands.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>This plugin has no configuration file.</p>`,16)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};